/// Runs `name` on the JSON array `args`; never unwinds into the caller.
pub fn call_json(name: &str, args: &str) -> String {
    let result = std::panic::catch_unwind(|| {
        let args: Vec<Value> = serde_json::from_str(args).map_err(|e| e.to_string())?;
        dispatch(name, &args)
    });
    match result {
        Ok(Ok(value)) => json!({"ok": value}),
        Ok(Err(message)) => json!({"error": message}),
        Err(panic) => {
            let message = panic
                .downcast_ref::<&str>()
                .map(ToString::to_string)
                .or_else(|| panic.downcast_ref::<String>().cloned())
                .unwrap_or_else(|| "panic".into());
            json!({"panic": message})
        }
    }
    .to_string()
}

/// `static native String call(String name, String args)` of `rustanything.FullscreenRsNative`.
// SAFETY: the JNI symbol name of that method; nothing else defines it.
#[unsafe(no_mangle)]
pub extern "system" fn Java_rustanything_FullscreenRsNative_call<'local>(
    mut env: jni::JNIEnv<'local>,
    _class: jni::objects::JClass<'local>,
    name: jni::objects::JString<'local>,
    args: jni::objects::JString<'local>,
) -> jni::sys::jstring {
    let read = |env: &mut jni::JNIEnv<'local>, s: &jni::objects::JString<'local>| -> String {
        env.get_string(s).map(Into::into).unwrap_or_default()
    };
    let name = read(&mut env, &name);
    let args = read(&mut env, &args);
    env.new_string(call_json(&name, &args))
        .map_or(std::ptr::null_mut(), jni::objects::JString::into_raw)
}

/// `rustanything.RustAnythingError` and its `(String, String)` constructor, resolved once per process.
type Exception = (jni::objects::GlobalRef, jni::objects::JMethodID);
static RUST_ANYTHING_ERROR: std::sync::OnceLock<Option<Exception>> = std::sync::OnceLock::new();

fn rust_anything_error(env: &mut jni::JNIEnv) -> Option<Exception> {
    RUST_ANYTHING_ERROR
        .get_or_init(|| {
            let class = env.find_class("rustanything/RustAnythingError").ok()?;
            let ctor = env
                .get_method_id(&class, "<init>", "(Ljava/lang/String;Ljava/lang/String;)V")
                .ok()?;
            Some((env.new_global_ref(class).ok()?, ctor))
        })
        .clone()
}

/// Splits `"Type: message"`; anything else is a RuntimeException with the whole message.
fn split_error(message: &str) -> (&str, &str) {
    message
        .split_once(": ")
        .filter(|(k, _)| {
            k.starts_with(|c: char| c.is_ascii_alphabetic())
                && k.chars()
                    .all(|c| c.is_ascii_alphanumeric() || matches!(c, '.' | '_' | '$'))
        })
        .unwrap_or(("RuntimeException", message))
}

#[allow(dead_code)]
/// Hands an error back through the caller's `String[2]` slot: type and message. The Java side
/// throws it, which is much cheaper than an exception raised from native code.
fn report(env: &mut jni::JNIEnv, slot: &jni::objects::JObjectArray, message: &str) {
    let (kind, text) = split_error(message);
    if let (Ok(kind), Ok(text)) = (env.new_string(kind), env.new_string(text)) {
        let _ = env.set_object_array_element(slot, 0, &kind);
        let _ = env.set_object_array_element(slot, 1, &text);
    }
}

#[allow(dead_code)]
/// Throws `"Type: message"` as a `RustAnythingError` without a stack trace, which is cheap from
/// native code; the generated Java turns it into a `Type` exception, built in Java.
fn throw(env: &mut jni::JNIEnv, message: &str) {
    let (kind, text) = split_error(message);
    let Some((class, ctor)) = rust_anything_error(env) else {
        let _ = env.exception_clear();
        let _ = env.throw_new("java/lang/RuntimeException", message);
        return;
    };
    let (Ok(kind), Ok(text)) = (env.new_string(kind), env.new_string(text)) else {
        return;
    };
    let class: &jni::objects::JClass = class.as_obj().into();
    let args = [
        jni::objects::JValue::Object(&kind).as_jni(),
        jni::objects::JValue::Object(&text).as_jni(),
    ];
    // SAFETY: `ctor` is the `(String, String)` constructor of `class`, looked up together, and
    // both arguments are Strings.
    if let Ok(object) = unsafe { env.new_object_unchecked(class, ctor, &args) } {
        let _ = env.throw(jni::objects::JThrowable::from(object));
    }
}

/// Runs the port; a panic becomes an error instead of unwinding into the JVM.
#[allow(dead_code)]
fn run<T>(f: impl FnOnce() -> Result<T, String>) -> Result<T, String> {
    std::panic::catch_unwind(std::panic::AssertUnwindSafe(f)).unwrap_or_else(|panic| {
        let text = panic
            .downcast_ref::<&str>()
            .map(ToString::to_string)
            .or_else(|| panic.downcast_ref::<String>().cloned())
            .unwrap_or_default();
        Err(format!("RuntimeException: Rust panic: {text}"))
    })
}

/// A `String` argument; `None` (with a NullPointerException thrown) for null.
#[allow(dead_code)]
fn string_arg(env: &mut jni::JNIEnv, s: &jni::objects::JString) -> Option<String> {
    if s.is_null() {
        let _ = env.throw_new("java/lang/NullPointerException", "null String argument");
        return None;
    }
    let raw = env.get_raw();
    let mut stack = [0u16; 128];
    // SAFETY: `raw` is this thread's JNIEnv and `s` a live, non-null String reference; the JVM
    // fills every entry of the function table.
    let len = unsafe { ((**raw).GetStringLength?)(raw, s.as_raw()) };
    let n = usize::try_from(len).unwrap_or(0);
    let mut heap = Vec::new();
    let units: &mut [u16] = if n <= stack.len() {
        &mut stack[..n]
    } else {
        heap.resize(n, 0);
        &mut heap
    };
    // SAFETY: as above; `units` holds exactly `len` UTF-16 code units.
    unsafe { ((**raw).GetStringRegion?)(raw, s.as_raw(), 0, len, units.as_mut_ptr()) };
    // UTF-16 straight from the String: no modified UTF-8 in between.
    Some(String::from_utf16_lossy(units))
}

/// A Java String from Rust text, built from UTF-16 (`NewString`), not modified UTF-8.
#[allow(dead_code)]
fn java_string(env: &mut jni::JNIEnv, text: &str) -> jni::sys::jstring {
    let mut stack = [0u16; 128];
    let mut heap = Vec::new();
    let units: &[u16] = if text.len() <= stack.len() {
        let mut n = 0;
        for u in text.encode_utf16() {
            stack[n] = u;
            n += 1;
        }
        &stack[..n]
    } else {
        heap.extend(text.encode_utf16());
        &heap
    };
    let Ok(len) = jni::sys::jsize::try_from(units.len()) else {
        return std::ptr::null_mut();
    };
    let raw = env.get_raw();
    // SAFETY: `raw` is this thread's JNIEnv, valid for the call.
    let Some(new_string) = (unsafe { (**raw).NewString }) else {
        return std::ptr::null_mut();
    };
    // SAFETY: `units` holds `len` UTF-16 code units, read during the call only.
    unsafe { new_string(raw, units.as_ptr(), len) }
}

